        return Owner.membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate());
    }

    /**
     * Compute the owner's membership tier, the derived tier based on the owner's namesake count and
     * whether an email is present (see {@link Owner#membershipTier(Integer, String)}).
     */
    default String formatMembershipTier(Owner owner) {
        if (owner == null) {
            return null;
        }
        return Owner.membershipTier(owner.getNamesakeCount(), owner.getEmail());
    }

    /**
     * Compute the owner's locality, the canonical region derived from the owner's city using the
     * fixed city-to-region table (see {@link Owner#locality(String)}).
     */
    default String formatLocality(Owner owner) {
        if (owner == null) {
            return null;
        }
        return Owner.locality(owner.getCity());
    }

    Owner toOwner(OwnerDto ownerDto);

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "pets", ignore = true)
    @Mapping(target = "customerCode", ignore = true)
    @Mapping(target = "namesakeCount", ignore = true)
    @Mapping(target = "telephone", qualifiedByName = "normalizeTelephone")
    Owner toOwner(OwnerFieldsDto ownerDto);

    /** Normalize a telephone to its canonical E.164 form, matching {@code TelephoneValidator}. */
    @Named("normalizeTelephone")
    default String normalizeTelephone(String telephone) {
        return Owner.normalizeTelephone(telephone);
    }

    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);

    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);

    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
        OwnerPageDto ownerPageDto = new OwnerPageDto();
        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
        ownerPageDto.setPage(ownerPage.getNumber());
        ownerPageDto.setSize(ownerPage.getSize());
        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
        return ownerPageDto;
    }
}

